// ЗГЕНЕРОВАНО `deno task scaffold:template` з create/template/** — не редагувати.
//
// Чому шаблон вбудований, а не читається з диска — у
// tools/generate-scaffold-template.ts.

export const TEMPLATE: Record<string, string> = {
  ".env.example": "# Скопіюй у .env і заповни. Той самий файл читає docker-compose.\nDB_HOST=localhost\nDB_PORT=5432\nDB_NAME={{name}}\nDB_USERNAME={{name}}\nDB_PASSWORD=change-me\n\nPORT=3000\n# Секрет підпису токенів вкладень (HMAC). JWT_SECRET читається як legacy-фолбек.\n# У продуктивному оточенні плейсхолдер нижче валить старт сервера — згенеруй власний.\nBLOB_TOKEN_SECRET=change-me-in-production\nAUTH_SESSION_TTL_HOURS=720\n# У продуктиві cookie сесії завжди Secure (дефолт); локально по http лишай порожнім.\nAUTH_COOKIE_SECURE=\n\n# Логін+пароль разом → на старті створиться адміністратор.\nBOOTSTRAP_LOGIN=admin\nBOOTSTRAP_PASSWORD=\n\n# Непорожній → сервер віддає в'ю через Vite (режим розробки).\nVITE_DEV_URL=http://localhost:5173\n",
  ".gitignore": ".env\ndist/\nnode_modules/\nvendor/\napp/_sqlpackage/*.sql\n",
  "app/_generated/agent-routes.generated.ts": "// Заглушка. Перезаписує `deno task sql:registry`.\nexport const agentModelRoutes = {};\n",
  "app/_generated/model-registry.generated.ts": "// Заглушка. Перезаписує `deno task sql:registry` — запусти його після створення\n// першої моделі (app/<family>/<model>/manifest.json).\n//\n// Типи навмисно не виписані: порожні літерали приймаються обома контрактами\n// bootstrap(), а анотація тут розійшлася б із фреймворком при першому ж\n// уточненні його типів.\nexport const generatedModelRegistry = {};\nexport const generatedTsCommandBindings = [];\n",
  "app/_generated/view-manifest.generated.ts": "// Заглушка. Перезаписує `deno task sql:registry`.\nexport const viewManifest = [];\n",
  "app/_locales/en.json": "{\n  \"app.title\": \"{{name}}\"\n}\n",
  "app/_locales/uk.json": "{\n  \"app.title\": \"{{name}}\"\n}\n",
  "app/_public/.gitkeep": "",
  "app/admin/menu/db/data.sql": "-- Склад меню — дані ЦЬОГО застосунку, тому лежить тут, а не в ядрі.\n--\n-- Поки моделей немає, меню порожнє: пункт має вказувати на реальний маршрут\n-- в'ю (`family/model/view`), інакше користувач упреться в мертве посилання.\n-- Коли з'явиться перша модель, розкоментуй і заміни маршрут.\n--\n-- `on conflict do nothing` скрізь: сід створює меню на порожній базі й більше\n-- не втручається — публікація SQL не має відкочувати те, що адміністратор\n-- переставив чи перейменував.\n\ninsert into app.menu (code, name, is_active)\nvalues ('default', 'Основне меню', true)\non conflict (code) do nothing;\n\n-- Меню бачать усі групи, які мають на нього зв'язку.\ninsert into app.user_group_menu (user_group_id, menu_id, sort_order, is_active)\nselect g.id, m.id, 0, true\nfrom app.user_group g\ncross join app.menu m\nwhere m.code = 'default'\non conflict (user_group_id, menu_id) do nothing;\n\n-- insert into app.menu_item (menu_id, parent_id, code, name, route_path, sort_order)\n-- select m.id, null, 'catalog', 'Довідники', null, 10 from app.menu m where m.code = 'default'\n-- on conflict do nothing;\n",
  "app/admin/menu/manifest.json": "{\n  \"//\": \"Меню — модель рантайму, хоч її структура й функції живуть у ядрі (@core/menu). Без цього манифесту команда menu/current не зареєстрована, і оболонка лишається без меню — сервер відповідає «Команду «menu/current» не налаштовано».\",\n  \"model\": \"menu\",\n  \"type\": \"catalog\",\n  \"//sql\": \"Генерувати нічого: CRUD меню написаний руками в ядрі.\",\n  \"sql\": { \"generate\": false },\n  \"schema\": \"app\",\n  \"//commands\": \"Нестандартна команда мусить оголосити своє право, інакше рантайм її не виконає (fail-closed). `authenticated` — «досить бути авторизованим»: menu/current кличе кожен вхід, і вимагати право на модель menu означало б лишити без меню всіх, крім адміністратора.\",\n  \"commands\": {\n    \"sql\": { \"current\": \"menu_current\", \"copy\": \"menu_copy\" },\n    \"access\": { \"current\": \"authenticated\", \"copy\": \"create\" }\n  }\n}\n",
  "app/header/app-header.ts": "import { html, type TemplateResult } from \"lit\";\nimport { customElement } from \"lit/decorators.js\";\nimport { SignalWatcher } from \"@lit-labs/signals\";\nimport { GlobalStyledLitElement } from \"@client/ui-kit/base/gsle.ts\";\nimport { currentUser, logout } from \"@client/auth/session.ts\";\n\nexport const tagName = \"app-header\";\n\nconst Base = SignalWatcher(GlobalStyledLitElement);\n\n/** Шапка застосунку: назва зліва, користувач і вихід справа. */\n@customElement(tagName)\nexport class AppHeader extends Base {\n  override render(): TemplateResult {\n    const user = currentUser();\n\n    return html`\n      <div class=\"flex items-center justify-between px-4 py-2 bg-primary text-primary-content\">\n        <span class=\"font-medium\">{{name}}</span>\n        <span class=\"flex items-center gap-3\">\n          <span class=\"opacity-80\">${user?.fullName ?? user?.login ?? \"\"}</span>\n          <button class=\"btn btn-sm\" @click=${this.#logout}>Вийти</button>\n        </span>\n      </div>\n    `;\n  }\n\n  async #logout() {\n    await logout();\n    location.reload();\n  }\n}\n",
  "app/home-tab.ts": "import { html, type TemplateResult } from \"lit\";\nimport { customElement, query } from \"lit/decorators.js\";\nimport { GlobalStyledLitElement } from \"@client/ui-kit/base/gsle.ts\";\n\nexport const tagName = \"home-tab\";\n\n/** Стартова вкладка. Заміни вміст на щось корисне для свого застосунку. */\n@customElement(tagName)\nexport class HomeTab extends GlobalStyledLitElement {\n  @query(\"dialog\") private dialogEl!: HTMLDialogElement;\n\n  override render(): TemplateResult {\n    return html`\n      <div class=\"p-6 flex flex-col gap-4 items-start\">\n        <div>\n          <h1 class=\"text-xl font-medium mb-2\">{{name}}</h1>\n          <p class=\"opacity-70\">\n            Пункти меню редагуються в адмініструванні; моделі створюються в\n            <code>app/&lt;family&gt;/&lt;model&gt;/</code>.\n          </p>\n        </div>\n\n        <!-- Заглушка під майбутню установку готового прикладного рішення —\n             моделі, SQL і зібрані чанки в'ю одним пакетом. Поки кнопка лише\n             показує, що така дія передбачена. -->\n        <button class=\"btn btn-primary\" @click=${() => this.dialogEl.showModal()}>\n          Завантажити прикладне рішення\n        </button>\n\n        <!-- m-auto тут не косметика: preflight Tailwind обнуляє margin усім\n             елементам, а нативне центрування модального dialog тримається саме\n             на margin: auto з UA-стилів. Без цього вікно прилипає до лівого\n             верхнього кута. (Зворотних лапок у коментарі всередині html-шаблона\n             бути не може — вони обривають сам шаблонний рядок.) -->\n        <dialog class=\"m-auto p-6 rounded border max-w-sm\">\n          <h2 class=\"text-lg font-medium mb-2\">Завантаження прикладного рішення</h2>\n          <p class=\"opacity-80 mb-4\">\n            Функція в стадії реалізації. Тут відкриється вибір пакета рішення —\n            моделі, SQL і форми одним архівом.\n          </p>\n          <form method=\"dialog\" class=\"flex justify-end\">\n            <button class=\"btn\">Зрозуміло</button>\n          </form>\n        </dialog>\n      </div>\n    `;\n  }\n}\n",
  "app/index.html": "<!doctype html>\n<html lang=\"uk\" data-theme=\"1c\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n    <title>{{name}}</title>\n    <style>\n      *, *::before, *::after { box-sizing: border-box; }\n      html, body { margin: 0; padding: 0; height: 100%; }\n      tab-controller { display: flex; height: 100%; }\n      #app { height: 100%; }\n    </style>\n  </head>\n  <body>\n    <div id=\"app\"></div>\n    <script type=\"module\" src=\"./main.ts\"></script>\n  </body>\n</html>\n",
  "app/login/app-login.ts": "import { html, type TemplateResult } from \"lit\";\nimport { customElement, state } from \"lit/decorators.js\";\nimport { GlobalStyledLitElement } from \"@client/ui-kit/base/gsle.ts\";\nimport {\n  changeOwnPassword,\n  createFirstUser,\n  fetchBootstrapState,\n  login,\n  mustChangePassword,\n  type BootstrapState,\n} from \"@client/auth/session.ts\";\n\nexport const tagName = \"app-login\";\n\n/**\n * Екран входу належить застосунку — фреймворк дає тільки виклики\n * (`@client/auth/session.ts`). Перший запуск не окрема сторінка, а стан цього ж\n * екрана: на порожній базі форма заводить першого адміністратора.\n */\n@customElement(tagName)\nexport class AppLogin extends GlobalStyledLitElement {\n  @state() private state: BootstrapState | null = null;\n  @state() private login = \"\";\n  @state() private password = \"\";\n  @state() private error = \"\";\n  @state() private busy = false;\n  /** Вхід відбувся, але пароль тимчасовий — показуємо зміну замість оболонки. */\n  @state() private changing = mustChangePassword();\n  @state() private newPassword = \"\";\n\n  override async connectedCallback() {\n    super.connectedCallback();\n    try {\n      this.state = await fetchBootstrapState();\n      this.login = this.state.predefinedLogin ?? \"\";\n    } catch (e) {\n      this.error = e instanceof Error ? e.message : String(e);\n    }\n  }\n\n  private get needsSetup(): boolean {\n    return !!this.state?.needsSetup && !this.state.predefinedUserAvailable;\n  }\n\n  override render(): TemplateResult {\n    if (this.changing) return this.#renderPasswordChange();\n\n    return html`\n      <div class=\"min-h-screen flex items-center justify-center\">\n        <form class=\"w-80 flex flex-col gap-3 p-6 rounded border\" @submit=${this.#submit}>\n          <h1 class=\"text-lg font-medium\">\n            ${this.needsSetup ? \"Перший запуск: створіть адміністратора\" : \"{{name}}\"}\n          </h1>\n\n          <input class=\"input\" placeholder=\"Логін\" .value=${this.login}\n                 @input=${(e: Event) => this.login = (e.target as HTMLInputElement).value} />\n          <input class=\"input\" type=\"password\" placeholder=\"Пароль\" .value=${this.password}\n                 @input=${(e: Event) => this.password = (e.target as HTMLInputElement).value} />\n\n          ${this.error ? html`<div class=\"text-error text-sm\">${this.error}</div>` : \"\"}\n\n          <button class=\"btn btn-primary\" ?disabled=${this.busy}>\n            ${this.needsSetup ? \"Створити й увійти\" : \"Увійти\"}\n          </button>\n        </form>\n      </div>\n    `;\n  }\n\n  /**\n   * Обов'язкова зміна пароля. Виникає, коли користувача створив bootstrap із\n   * BOOTSTRAP_PASSWORD: той пароль лежить відкритим текстом у .env і відомий\n   * усім, хто бачив файл. Пропустити екран не можна — сервер під цим\n   * прапорцем не виконує жодної команди моделі.\n   */\n  #renderPasswordChange(): TemplateResult {\n    return html`\n      <div class=\"min-h-screen flex items-center justify-center\">\n        <form class=\"w-80 flex flex-col gap-3 p-6 rounded border\" @submit=${this.#changePassword}>\n          <h1 class=\"text-lg font-medium\">Змініть тимчасовий пароль</h1>\n          <p class=\"text-sm opacity-70\">\n            Пароль задано в налаштуваннях сервера, тому працювати з ним не можна.\n          </p>\n\n          <input class=\"input\" type=\"password\" placeholder=\"Поточний пароль\" .value=${this.password}\n                 @input=${(e: Event) => this.password = (e.target as HTMLInputElement).value} />\n          <input class=\"input\" type=\"password\" placeholder=\"Новий пароль\" .value=${this.newPassword}\n                 @input=${(e: Event) => this.newPassword = (e.target as HTMLInputElement).value} />\n\n          ${this.error ? html`<div class=\"text-error text-sm\">${this.error}</div>` : \"\"}\n\n          <button class=\"btn btn-primary\" ?disabled=${this.busy}>Зберегти й продовжити</button>\n        </form>\n      </div>\n    `;\n  }\n\n  async #changePassword(event: Event) {\n    event.preventDefault();\n    this.busy = true;\n    this.error = \"\";\n\n    try {\n      await changeOwnPassword(this.password, this.newPassword);\n      location.reload();\n    } catch (e) {\n      this.error = e instanceof Error ? e.message : String(e);\n    } finally {\n      this.busy = false;\n    }\n  }\n\n  async #submit(event: Event) {\n    event.preventDefault();\n    this.busy = true;\n    this.error = \"\";\n\n    try {\n      if (this.needsSetup) {\n        await createFirstUser({ login: this.login.trim(), password: this.password, fullName: this.login.trim() });\n      } else {\n        await login({ login: this.login.trim(), password: this.password });\n      }\n      // Вхід міг привести до тимчасового пароля — тоді не перезавантажуємо\n      // сторінку, а перемикаємо цей самий екран у стан зміни.\n      if (mustChangePassword()) {\n        this.changing = true;\n        this.password = \"\";\n        return;\n      }\n\n      location.reload();\n    } catch (e) {\n      this.error = e instanceof Error ? e.message : String(e);\n    } finally {\n      this.busy = false;\n    }\n  }\n}\n",
  "app/main.ts": "// Composition root клієнта — тут (і тільки тут) фреймворк зустрічається з\n// конкретним застосунком.\nimport \"./styles/app-styles.ts\";\n\nimport { registerShell } from \"@client/shell/shell-registry.ts\";\nimport { initDataService } from \"@client/data/data-service.ts\";\nimport { mustChangePassword, restoreSession } from \"@client/auth/session.ts\";\nimport { setLocale } from \"@client/locale.ts\";\n\nimport \"./header/app-header.ts\";\nimport \"./menu/app-menu.ts\";\nimport \"./home-tab.ts\";\nimport \"./login/app-login.ts\";\n\nregisterShell({ header: \"app-header\", menu: \"app-menu\", home: \"home-tab\", login: \"app-login\" });\ninitDataService();\n\nasync function boot() {\n  await setLocale(\"uk\");\n\n  const host = document.getElementById(\"app\")!;\n  const authorized = await restoreSession();\n\n  // Тимчасовий пароль зупиняє тут: оболонку піднімати нема сенсу — сервер під\n  // цим прапорцем не виконує жодної команди моделі. Екран зміни — той самий\n  // app-login, лише в іншому стані.\n  if (!authorized || mustChangePassword()) {\n    host.replaceChildren(document.createElement(\"app-login\"));\n    return;\n  }\n\n  // Динамічно: неавторизований користувач не тягне граф UI. Верхньорівневого\n  // await тут немає навмисно — він давав цикл entry → import → entry.\n  await import(\"@client/tabs/tab-controller.ts\");\n  host.replaceChildren(document.createElement(\"tab-controller\"));\n}\n\nboot().catch((error) => {\n  console.error(\"[boot]\", error);\n  document.getElementById(\"app\")!.replaceChildren(document.createElement(\"app-login\"));\n});\n",
  "app/menu/app-menu.ts": "import { html, nothing, type TemplateResult } from \"lit\";\nimport { customElement, state } from \"lit/decorators.js\";\nimport { GlobalStyledLitElement } from \"@client/ui-kit/base/gsle.ts\";\nimport { bus } from \"@client/bus/bus.ts\";\n\nexport const tagName = \"app-menu\";\n\ninterface MenuItem {\n  code: string;\n  name: string;\n  routePath: string | null;\n  children?: MenuItem[];\n}\n\n/**\n * Меню користувача. Склад приходить з БД командою `menu/current` — вона зливає\n * меню всіх груп користувача й лишає тільки пункти, на модель яких є право\n * `view`. Тому фільтрувати тут нічого не треба.\n */\n@customElement(tagName)\nexport class AppMenu extends GlobalStyledLitElement {\n  @state() private items: MenuItem[] = [];\n\n  override async connectedCallback() {\n    super.connectedCallback();\n    // Конверт звужуємо явно: bus.request типізований узагальнено, а форму\n    // відповіді знає тільки той, хто кличе конкретну команду.\n    const envelope = await bus.request(\"data.load\", {\n      model: \"menu\",\n      command: \"current\",\n      payload: {},\n    }) as { data?: { rows?: unknown[] } } | undefined;\n\n    this.items = (envelope?.data?.rows ?? []) as MenuItem[];\n  }\n\n  override render(): TemplateResult {\n    return html`<nav class=\"p-2 w-56 overflow-auto\">${this.items.map((item) => this.#renderItem(item))}</nav>`;\n  }\n\n  #renderItem(item: MenuItem): TemplateResult {\n    if (!item.routePath) {\n      return html`\n        <div class=\"mt-3 mb-1 text-xs uppercase opacity-60\">${item.name}</div>\n        ${(item.children ?? []).map((child) => this.#renderItem(child))}\n      `;\n    }\n\n    return html`\n      <a class=\"block px-2 py-1 rounded cursor-pointer hover:bg-base-200\"\n         @click=${() => bus.emit({ type: \"tab.open\", route: item.routePath! })}>\n        ${item.name}\n      </a>\n      ${item.children?.length ? item.children.map((child) => this.#renderItem(child)) : nothing}\n    `;\n  }\n}\n",
  "app/server.ts": "/// <reference lib=\"deno.ns\" />\n// Composition root бекенду: тут (і тільки тут) застосунок зустрічається з\n// фреймворком. Бібліотека нічого не шукає сама — усе приходить одним\n// типізованим аргументом bootstrap().\nimport { fromFileUrl } from \"jsr:@std/path@^1.1.2\";\nimport { serveDir } from \"jsr:@std/http@^1.0.18/file-server\";\n\nimport { bootstrap, configFromEnv } from \"@altera/server\";\n\nimport { generatedModelRegistry, generatedTsCommandBindings } from \"./_generated/model-registry.generated.ts\";\nimport { agentModelRoutes } from \"./_generated/agent-routes.generated.ts\";\nimport { viewManifest } from \"./_generated/view-manifest.generated.ts\";\n\n// Корінь проєкту — батьківський каталог app/.\nconst projectRoot = fromFileUrl(new URL(\"../\", import.meta.url)).replace(/\\/$/, \"\");\n// Сюди збирає Vite (root: \"app\", outDir: \"../dist\").\nconst frontendDistDir = `${projectRoot}/dist/`;\nconst frontendIndexFile = `${frontendDistDir}index.html`;\n\nasync function pathExists(path: string): Promise<boolean> {\n  try {\n    await Deno.stat(path);\n    return true;\n  } catch {\n    return false;\n  }\n}\n\nexport async function createServer() {\n  const application = await bootstrap({\n    ...configFromEnv(),\n    models: { registry: generatedModelRegistry, tsCommands: generatedTsCommandBindings },\n    agentRoutes: agentModelRoutes,\n    views: {\n      manifest: viewManifest,\n      projectRoot,\n      // Root Vite: ключі в dist/.vite/manifest.json рахуються від нього, а\n      // шляхи в маніфесті в'ю — від кореня проєкту.\n      appDir: \"app\",\n      // З VITE_DEV_URL в'ю віддає Vite (вихідні модулі через /@fs).\n      dev: !!Deno.env.get(\"VITE_DEV_URL\"),\n    },\n  });\n\n  const hono = application.router;\n  const apiHandler = hono.fetch.bind(hono);\n  const hasFrontendDist = await pathExists(frontendDistDir);\n\n  const handler = async (request: Request): Promise<Response> => {\n    const pathname = new URL(request.url).pathname;\n\n    if (!pathname.startsWith(\"/api\") && hasFrontendDist) {\n      const staticResponse = await serveDir(request, { fsRoot: frontendDistDir, quiet: true });\n      if (staticResponse.status !== 404) return staticResponse;\n\n      // SPA-фолбек: усе, що не схоже на файл, віддаємо index.html.\n      const looksLikeAsset = (pathname.split(\"/\").pop() ?? \"\").includes(\".\");\n      if (request.method === \"GET\" && !looksLikeAsset) {\n        return new Response(await Deno.readFile(frontendIndexFile), {\n          status: 200,\n          headers: { \"content-type\": \"text/html; charset=utf-8\" },\n        });\n      }\n    }\n\n    return await apiHandler(request);\n  };\n\n  return { handler, close: () => application.close() };\n}\n\nif (import.meta.main) {\n  const port = Number(Deno.env.get(\"PORT\") || 3000);\n  const viteDevUrl = Deno.env.get(\"VITE_DEV_URL\");\n  const { handler } = await createServer();\n  Deno.serve({ port }, handler);\n  console.log(`🚀 {{name}} на http://localhost:${port}`);\n  if (viteDevUrl) {\n    console.log(`   в'ю — з Vite: інтерфейс відкривай на ${viteDevUrl}, тут живе тільки /api`);\n  }\n}\n",
  "app/sql.json": "{\n  \"//\": \"Порядок важливий: пакети ядра й моделі застосунку чергуються за FK. @core/document_core посилається на catalog/organization, currency і chart_of_account — додай його НИЖЧЕ за ці моделі, коли вони з'являться. Запис admin/menu — це лише манифест і сід застосунку: структура й функції меню живуть у ядрі (@core/menu).\",\n  \"output\": \"{{name}}.app.sql\",\n  \"outputs\": {\n    \"structure\": \"{{name}}.struc_app.sql\",\n    \"models\": \"{{name}}.models_app.sql\",\n    \"migrations\": \"{{name}}.migration_app.sql\",\n    \"data\": \"{{name}}.data_app.sql\"\n  },\n  \"models\": [\n    \"@core/base\",\n    \"@core/access\",\n    \"@core/menu\",\n    \"admin/menu\",\n    \"@core/attachment\"\n  ]\n}\n",
  "app/styles/app-styles.ts": "// Місце, де зібраний Tailwind потрапляє у фреймворк. `?inline` — фіча Vite,\n// тому живе в застосунку: бібліотека такого імпорту дозволити собі не може.\nimport raw from \"./tailwind.css?inline\";\nimport { setAppStyles } from \"@client/shared/styles.ts\";\n\nsetAppStyles(raw);\n",
  "app/styles/tailwind.css": "/* Єдиний вхід збірки Tailwind. Належить застосунку, бо сканує його розмітку.\n *\n * Теми тут немає: фреймворк дописує її сам у setAppStyles() — правила в ній\n * безшарові й мусять перебивати utilities, і код це гарантує надійніше за\n * порядок рядків.\n */\n\n@import \"tailwindcss\";\n\n/* Класи, вжиті всередині фреймворку (іконки, тулбари). Авто-детекція Tailwind\n   сканує застосунок, але не vendor/, тож шлях указано явно. Він без версії —\n   апгрейд пакета його не ламає. `@source` НЕ приймає ані аліас Vite, ані ім'я\n   пакета: сканер читає директиву з диска, повз бандлер. */\n@source \"../../vendor/jsr.io/@altera\";\n\n@plugin \"daisyui\" {\n  themes: false;\n}\n\n@import \"@fontsource/roboto/400.css\";\n@import \"@fontsource/roboto/500.css\";\n@import \"@fontsource/roboto/700.css\";\n",
  "deno.json": "{\n  \"//\": \"Застосунок на фреймворку Altera. Три пакети приходять із jsr; усе, що нижче, належить застосунку.\",\n\n  \"//@client\": \"Аліас @client/ — на той самий пакет. Пиши імпорти саме через нього: пресет наводить його на каталог фреймворку у vendor/, тому забутий `deno install` ламає збірку одразу й голосно. Через ім'я пакета модулі прийшли б із кешу, і тихо зламалися б лише стилі. Коментар тут, а не в imports: усередині карти імпортів чужий ключ — це помилка адреси.\",\n  \"//vendor\": \"ОБОВ'ЯЗКОВО. Пресет Vite і Tailwind читають вихідники фреймворку з диска (аліас @client, @source), а кеш JSR — це файли з іменами-хешами. Вендоринг матеріалізує їх у справжнє дерево. Без нього збірка падає на завантаженні модулів фреймворку.\",\n  \"//configLoader\": \"--configLoader native: конфіг вантажить Deno, а не бандлер Vite. Без цього Rolldown бандлить vite.config.ts до того, як існують аліаси (їх задає сам конфіг), не резолвить `@client/vite.ts` і друкує UNRESOLVED_IMPORT на кожній збірці. Збірка при цьому правильна — імпорт стає зовнішнім і його резолвить Deno по карті імпортів, — але попередження маскувало б справжній неразрішений імпорт.\",\n  \"//vite\": \"Мажорна версія vite прив'язана до версії @altera/client: пресет фреймворку імпортує vite повним npm:-специфікатором, а `deno task dev:front` бере його звідси. Розійдуться — у застосунку буде ДВА екземпляри vite, і той, що виконується, мовчки проігнорує опції, написані для іншого (саме так зникає примусовий чанк shell-registry і повертається дедлок білої сторінки). Оновлювати обидва рядки разом.\",\n  \"vendor\": true,\n  \"nodeModulesDir\": \"auto\",\n\n  \"tasks\": {\n    \"dev\": \"deno task dev:server & deno task dev:front\",\n    \"dev:server\": \"deno run --allow-net --allow-read --allow-write --allow-env --allow-run --env-file --watch ./app/server.ts\",\n    \"dev:front\": \"deno run -A npm:vite --configLoader native\",\n    \"build:front\": \"deno run -A npm:vite build --configLoader native\",\n\n    \"sql:registry\": \"deno run -A jsr:@altera/tools/generate-model-runtime-registry ./app ./app/_generated/model-registry.generated.ts ./app/_generated/agent-routes.generated.ts ./app/_generated/view-manifest.generated.ts --verbose\",\n    \"sql:gen\": \"deno run -A jsr:@altera/tools/generate-model-sql ./app --verbose\",\n    \"sql:assemble\": \"deno run -A jsr:@altera/tools/assemble-sql-package ./app --verbose\",\n    \"sql:publish\": \"deno run -A --env-file jsr:@altera/tools/publish-sql ./app --verbose\",\n\n    \"startdb\": \"docker compose up -d\",\n    \"stopdb\": \"docker compose down\"\n  },\n\n  \"imports\": {\n    \"@altera/client\": \"jsr:@altera/client@^0.5.0\",\n    \"@client/\": \"jsr:/@altera/client@^0.5.0/\",\n    \"@altera/server\": \"jsr:@altera/server@^0.4.0\",\n    \"@app/\": \"./app/\",\n    \"@shared/\": \"./app/shared/\",\n\n    \"lit\": \"npm:lit@^3.3.1\",\n    \"@lit-labs/signals\": \"npm:@lit-labs/signals@^0.1.3\",\n    \"signal-polyfill\": \"npm:signal-polyfill@^0.2.2\",\n    \"signal-utils\": \"npm:signal-utils@^0.21.1\",\n    \"@sinclair/typebox\": \"npm:@sinclair/typebox@^0.34.0\",\n    \"@sinclair/typebox/value\": \"npm:@sinclair/typebox@^0.34.0/value\",\n    \"decimal.js\": \"npm:decimal.js@^10.6.0\",\n    \"@fontsource/roboto\": \"npm:@fontsource/roboto@^5.2.10\",\n\n    \"vite\": \"npm:vite@^8.2.0\",\n    \"tailwindcss\": \"npm:tailwindcss@^4.3.0\",\n    \"@tailwindcss/vite\": \"npm:@tailwindcss/vite@^4.3.0\",\n    \"daisyui\": \"npm:daisyui@^5.5.20\"\n  },\n\n  \"compilerOptions\": {\n    \"experimentalDecorators\": true,\n    \"emitDecoratorMetadata\": true,\n    \"strict\": true,\n    \"lib\": [\"deno.ns\", \"dom\", \"dom.iterable\", \"esnext\"]\n  }\n}\n",
  "docker-compose.yml": "services:\n  db:\n    image: postgres:17\n    restart: unless-stopped\n    environment:\n      POSTGRES_DB: ${DB_NAME}\n      POSTGRES_USER: ${DB_USERNAME}\n      POSTGRES_PASSWORD: ${DB_PASSWORD}\n    ports:\n      - \"${DB_PORT}:5432\"\n    volumes:\n      - dbdata:/var/lib/postgresql/data\n\nvolumes:\n  dbdata:\n",
  "tsconfig.json": "{\n  \"//\": \"Потрібен транспілятору всередині Vite (з Vite 8 це Oxc, до того був esbuild) — deno.json він не читає. Без цього файлу декоратори Lit транслюються за СТАНДАРТНОЮ семантикою, і застосунок падає в рантаймі з «Unsupported decorator location: field»: збірка проходить, типи проходять, API відповідає, а сторінка лишається білою. Найближчий tsconfig.json шукається вгору по каталогах, тож цей файл покриває і app/, і вендорені вихідники фреймворку у vendor/.\",\n  \"compilerOptions\": {\n    \"target\": \"ES2022\",\n    \"module\": \"ESNext\",\n    \"moduleResolution\": \"bundler\",\n    \"experimentalDecorators\": true,\n    \"useDefineForClassFields\": false,\n    \"strict\": true,\n    \"lib\": [\"ES2022\", \"DOM\", \"DOM.Iterable\"],\n    \"skipLibCheck\": true\n  },\n  \"include\": [\"app/**/*.ts\", \"vite.config.ts\"]\n}\n",
  "vite.config.ts": "// Уся машинерія Vite — у пресеті фреймворку: root, аліаси, чанки на в'ю,\n// проксі на бекенд, Tailwind, плагін Deno. Тут лишається тільки те, що\n// відрізняє застосунок.\nimport { defineAlteraConfig } from \"@altera/client/vite\";\n\nexport default defineAlteraConfig({ appDir: \"app\", apiPort: 3000 });\n",
};
